# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAY SARKACI PERİYODU VE YAYLARIN BAĞLANMASI</text>\n  <rect x="25" y="46" width="310" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Yay Sarkacı Periyot Bağıntısı</text>\n  <rect x="55" y="80" width="250" height="44" rx="8" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="108" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">T = 2π · kök(m / k)</text>\n  <text x="42" y="146" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">m:</tspan> Salınım yapan cismin kütlesi (kg)</text>\n  <text x="42" y="168" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">k:</tspan> Esnek yayın yay sabiti (N/m)</text>\n  <text x="42" y="192" font-size="11" font-weight="bold" fill="#dc2626">• Çekim ivmesine (g), eğik düzlem açısına ve</text>\n  <text x="52" y="208" font-size="11" font-weight="bold" fill="#dc2626">genliğe (r) BAĞLI DEĞİLDİR!</text>\n  <text x="42" y="228" font-size="10.5" fill="#1e3a8a">• Yay n eşit parçaya bölünürse her parçanın sabiti n·k olur.</text>\n  <rect x="355" y="46" width="320" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Eşdeğer Yay Sabiti (k_eş)</text>\n  <rect x="372" y="82" width="286" height="68" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="384" y="100" font-size="11.5" font-weight="bold" fill="#15803d">1. Seri Bağlı Yaylar (Uç Uca)</text>\n  <text x="384" y="120" font-size="11.5" font-weight="bold" fill="#14532d">1 / k_eş = 1 / k₁ + 1 / k₂  →  k_eş = (k₁·k₂)/(k₁+k₂)</text>\n  <text x="384" y="138" font-size="10.5" fill="#166534">Eşdeğer yay sabiti küçülür, periyot (T) artar.</text>\n  <rect x="372" y="160" width="286" height="68" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="384" y="178" font-size="11.5" font-weight="bold" fill="#15803d">2. Paralel Bağlı Yaylar (Yan Yana / İki Yandan)</text>\n  <text x="384" y="198" font-size="11.5" font-weight="bold" fill="#14532d">k_eş = k₁ + k₂</text>\n  <text x="384" y="216" font-size="10.5" fill="#166534">Eşdeğer yay sabiti büyür, periyot (T) azalır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BASİT SARKAÇ PERİYODU VE ÇİVİLİ SARKAÇ UYGULAMASI</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Basit Sarkaç Periyot Bağıntısı (α ≤ 10°)</text>\n  <rect x="55" y="80" width="255" height="44" rx="8" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="182" y="108" text-anchor="middle" font-size="16" font-weight="bold" fill="#b45309">T = 2π · kök(L / g)</text>\n  <text x="42" y="146" font-size="11.5" fill="#78350f">• <tspan font-weight="bold">L:</tspan> İpin boyu (m) · <tspan font-weight="bold">g:</tspan> Çekim ivmesi (m/s²)</text>\n  <text x="42" y="170" font-size="11" font-weight="bold" fill="#dc2626">• Cismin kütlesine (m) ve küçük açılarda</text>\n  <text x="52" y="186" font-size="11" font-weight="bold" fill="#dc2626">salınım açısına (α) BAĞLI DEĞİLDİR!</text>\n  <text x="42" y="210" font-size="10.5" fill="#78350f">• Ekvatordan kutuplara gidildikçe g artar, T azalır.</text>\n  <text x="42" y="226" font-size="10.5" fill="#78350f">• Saniyeleri vuran sarkacın periyodu T = 2 saniyedir.</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Çivili Sarkaçta Periyot Hesabı</text>\n  <line x1="450" y1="80" x2="550" y2="80" stroke="#475569" stroke-width="4"/>\n  <line x1="500" y1="80" x2="465" y2="175" stroke="#6b21a8" stroke-width="2"/>\n  <circle cx="465" cy="175" r="9" fill="#9333ea"/>\n  <circle cx="500" cy="130" r="4" fill="#dc2626"/>\n  <text x="518" y="134" font-size="10.5" font-weight="bold" fill="#dc2626">Çivi</text>\n  <line x1="500" y1="130" x2="530" y2="170" stroke="#16a34a" stroke-width="2" stroke-dasharray="4,2"/>\n  <circle cx="530" cy="170" r="9" fill="#16a34a"/>\n  <text x="452" y="125" font-size="11" font-weight="bold" fill="#6b21a8">L₁</text>\n  <text x="528" y="152" font-size="11" font-weight="bold" fill="#16a34a">L₂</text>\n  <rect x="378" y="190" width="278" height="40" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="517" y="214" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">T_sistem = (T₁ + T₂) / 2</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İVMELİ ASANSÖR İÇİNDEKİ SARKAÇLARIN PERİYOT DEĞİŞİMİ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. Yay Sarkacı (Her Durumda)</text>\n  <text x="40" y="98" font-size="11" fill="#1e3a8a">• T = 2π · kök(m / k) bağıntısında</text>\n  <text x="48" y="114" font-size="11" fill="#1e3a8a">çekim ivmesi (g) yer almaz.</text>\n  <text x="40" y="138" font-size="11" fill="#1e3a8a">• Asansör hızlansa da, yavaşlasa</text>\n  <text x="48" y="154" font-size="11" fill="#1e3a8a">da, Ay\'a götürülse de:</text>\n  <rect x="40" y="172" width="175" height="48" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="127" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Periyot (T) DEĞİŞMEZ!</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. Basit Sarkaç: g_etkin = g + a</text>\n  <text x="260" y="98" font-size="11" fill="#14532d">• Yukarı yönde <tspan font-weight="bold">hızlanan</tspan> veya</text>\n  <text x="260" y="116" font-size="11" fill="#14532d">• Aşağı yönde <tspan font-weight="bold">yavaşlayan</tspan> asansör</text>\n  <text x="260" y="140" font-size="11" font-weight="bold" fill="#15803d">→ T = 2π · kök(L / (g + a))</text>\n  <rect x="260" y="172" width="178" height="48" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="349" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Etkin ivme büyür,</text>\n  <text x="349" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Periyot (T) AZALIR!</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">3. Basit Sarkaç: g_etkin = g - a</text>\n  <text x="483" y="98" font-size="11" fill="#7f1d1d">• Aşağı yönde <tspan font-weight="bold">hızlanan</tspan> veya</text>\n  <text x="483" y="116" font-size="11" fill="#7f1d1d">• Yukarı yönde <tspan font-weight="bold">yavaşlayan</tspan> asansör</text>\n  <text x="483" y="140" font-size="11" font-weight="bold" fill="#b91c1c">→ T = 2π · kök(L / (g - a))</text>\n  <rect x="483" y="172" width="178" height="48" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="572" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">Etkin ivme küçülür,</text>\n  <text x="572" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">Periyot (T) ARTAR!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
